insert into news_stories (slug, publish_date, lane, tag, headline, summary, concept_note, source_name, source_url, card_id, status, teaser_title, teaser, featured, published_at, rank)
values
($n$2026-11-14-exports-30pc$n$, '2026-11-14', $n$india$n$, $n$TRADE$n$,
  $n$India's total exports jump nearly 30% to $89.99 billion in October; overall trade deficit narrows to $20.09 billion$n$,
  $n$India's combined exports of goods and services rose to $89.99 billion in October from $69.27 billion a year earlier, according to Commerce Ministry data released on Friday. Merchandise exports alone climbed about 45% to a record $49.47 billion, while goods imports rose to $89.35 billion from $76.69 billion. The overall trade deficit shrank to $20.09 billion from $25.15 billion because exports grew faster than imports. Services exports were estimated at $40.51 billion, and the ministry noted that its October services figures are estimates because the latest RBI services data covers only September. On goods alone, the gap was still close to $40 billion.$n$,
  $n$The law of demand says buyers purchase more when a product becomes cheaper for them, and that holds for foreign buyers too. A weaker rupee lowers the dollar price of Indian goods, which is one reason economists watch the currency so closely when export numbers come out.$n$,
  $n$The Tribune (ANI); also Millennium Post$n$, $n$https://www.tribuneindia.com/news/export-growth/indias-exports-surge-nearly-30-to-usd-89-99-billion-in-october-trade-deficit-narrows-to-usd-20-09-billion$n$, $n$econ-01$n$, 'draft',
  $n$India sold a record $49 billion of goods abroad in October, 45% more than a year ago.$n$,
  $n$Combined exports of goods and services rose almost 30%, and the overall trade gap shrank to about $20 billion. The goods-only gap is still close to $40 billion. The law of demand card explains why the price foreign buyers pay shapes how much India sells.$n$, false, $n$2026-11-13T14:28:00+05:30$n$, 1),
($n$2026-11-14-tata-motors-pv-loss$n$, '2026-11-14', $n$recruiter$n$, $n$RESULTS$n$,
  $n$Tata Motors Passenger Vehicles posts ₹5,531 crore Q2 loss on a ₹6,738 crore one-time charge, even as revenue rises 34%$n$,
  $n$Tata Motors Passenger Vehicles, which owns Jaguar Land Rover, reported a consolidated net loss of ₹5,531 crore for the July-September quarter, according to results released after market hours on Friday. Revenue rose 34% to ₹96,920 crore from ₹72,349 crore a year earlier. The loss was driven by an exceptional charge of ₹6,738 crore, larger than the loss itself, while restructuring at JLR, which is still recovering from last year's cyberattack, weighed on group earnings. CFO Dhiman Gupta said the priorities are new launches, faster cost cuts and better cash generation. The shares had closed 3.5% lower at ₹287 before the results came out.$n$,
  $n$When a company commits to a restructuring, accounting rules generally require it to recognise the expected cost as a provision right away instead of spreading it over future years. That is how a business with rising revenue can still show a large loss in a single quarter.$n$,
  $n$Free Press Journal; also Business Standard$n$, $n$https://www.freepressjournal.in/business/tata-motors-pv-swings-to-5531-crore-q2-loss-jlr-restructuring-weighs$n$, $n$acct-19$n$, 'draft',
  $n$Tata's car business grew sales 34%, yet it reported a ₹5,531 crore loss. One big charge explains it.$n$,
  $n$A one-time ₹6,738 crore charge, bigger than the loss itself, turned a quarter of sharply higher sales into a loss, with restructuring at Jaguar Land Rover weighing on earnings. The provisions card explains why such costs land all at once.$n$, false, $n$2026-11-13T18:42:00+05:30$n$, 2),
($n$2026-11-14-tata-trusts-feud$n$, '2026-11-14', $n$recruiter$n$, $n$GOVERNANCE$n$,
  $n$Tata Trusts vice-chairmen Venu Srinivasan and Vijay Singh hit back at trustee Darius Khambata over Tata Sons listing$n$,
  $n$Tata Trusts vice-chairmen Venu Srinivasan and Vijay Singh have rebutted trustee Darius Khambata in a five-page letter dated November 11, according to reports on Friday. Khambata had criticised decisions taken by the Tata Sons board on September 17 on a listing and on chairman N Chandrasekaran's reappointment. The two argued that the RBI's refusal to let Tata Sons give up its NBFC registration, which pushes it towards a stock market listing, was not a failure of advocacy, and that listing would not affect the Trusts' shareholding, dividends or charity work. Trusts chairman Noel Tata and Khambata oppose both the listing and Chandrasekaran's reappointment. The Trusts together own about 66% of Tata Sons.$n$,
  $n$Corporate governance is about who controls a company and how they are held accountable. Here the controlling shareholder, the Tata Trusts, is split over whether listing Tata Sons, which would bring outside shareholders and stricter disclosure, protects or weakens the group.$n$,
  $n$Millennium Post; also Business Standard, The Hans India$n$, $n$https://www.millenniumpost.in/business/tata-feud-venu-srinivasan-vijay-singh-hit-back-at-darius-khambata-683146$n$, $n$ethics-12$n$, 'draft',
  $n$The trusts that own two-thirds of Tata Sons can't agree on who should run the Tata group.$n$,
  $n$Two Tata Trusts vice-chairmen fired back at a fellow trustee in a five-page letter over listing Tata Sons and renewing chairman N Chandrasekaran's term. The RBI's ruling has pushed the question onto the table. The corporate governance card explains what is really at stake.$n$, false, $n$2026-11-14T00:21:00+05:30$n$, 3),
($n$2026-11-14-current-account-deficit$n$, '2026-11-14', $n$india$n$, $n$ECONOMY$n$,
  $n$India's current account deficit widens to $7.4 billion in September as income outflows jump; April-September gap at $25.8 billion$n$,
  $n$India's current account deficit rose to $7.4 billion in September from $5.2 billion a year earlier, according to preliminary RBI balance of payments data released on Friday. The goods trade deficit actually narrowed to $30 billion from $33.4 billion, and net services earnings rose slightly to $19.2 billion, but net income outflows more than tripled to $7.6 billion. Capital flows more than covered the gap: net capital inflows of $16.2 billion, helped by $22.2 billion of banking capital, gave an overall balance of payments surplus of $8.8 billion. For April to September, the current account deficit was $25.8 billion against $18 billion a year ago.$n$,
  $n$The balance of payments works like double-entry bookkeeping: every dollar India spends abroad must be matched by a dollar coming in somewhere else. A deficit on the current account is balanced by inflows on the capital account, which is why the overall balance can still show a surplus.$n$,
  $n$Millennium Post; also Daily Excelsior, The Hans India$n$, $n$https://www.millenniumpost.in/business/indias-current-account-deficit-widens-to-74-bn-in-september-683131$n$, $n$acct-14$n$, 'draft',
  $n$India spent $7.4 billion more abroad than it earned in September, yet still ended the month with a surplus.$n$,
  $n$The current account gap widened as income paid to foreigners more than tripled, but bank inflows of $22 billion more than covered it. The result was an $8.8 billion overall surplus. The double entry card shows why every outflow needs a matching inflow.$n$, false, $n$2026-11-13T23:07:00+05:30$n$, 4),
($n$2026-11-14-sensex-falls-319$n$, '2026-11-14', $n$india$n$, $n$MARKETS$n$,
  $n$Sensex falls 319 points and Nifty slips to 25,144 as oil near $96 and 6.09% inflation stoke rate-hike fears$n$,
  $n$The Sensex fell 318.56 points, or 0.39%, to close at 81,592.45 on Friday, and the Nifty 50 dropped 155.05 points, or 0.61%, to 25,144.30, ending a three-day winning run. Brent crude near $95.7 a barrel and October retail inflation of 6.09%, above the RBI's 6% ceiling, raised expectations of a rate hike. Every sector index except FMCG fell, with autos, metals and realty down about 1% each; Shriram Finance and Tata Motors Passenger Vehicles were the biggest Nifty losers. Foreign investors had bought ₹7,831 crore of shares on Thursday, and both indices still ended the week higher for a third straight week. The rupee weakened 21 paise to 94.24 per dollar.$n$,
  $n$Inflation, oil prices and interest rates are macro-environment forces that no single company controls, yet they move the whole market. The PESTLE framework groups them under the Economic factor that every business has to plan around.$n$,
  $n$HDFC Sky; also Millennium Post$n$, $n$https://hdfcsky.com/news/market-close-report-today-november-13-2026-nifty-sensex-decline-as-inflation-oil-weigh$n$, $n$mkt-05$n$, 'draft',
  $n$Costlier oil and 6% inflation broke the Sensex's three-day winning streak.$n$,
  $n$Markets fell on Friday as traders bet the RBI may have to raise interest rates, though the Sensex still gained for a third week in a row. Only FMCG stocks rose. The marketing environment card explains how macro forces like these hit every company at once.$n$, false, $n$2026-11-13T16:24:00+05:30$n$, 5),
($n$2026-11-14-wall-street-nvidia-yields$n$, '2026-11-14', $n$global$n$, $n$MARKETS$n$,
  $n$S&P 500 slips 0.4% as Nvidia and AI stocks fall again, but posts its first weekly gain since October; US 10-year yield hits 5.15%$n$,
  $n$The S&P 500 fell 0.4% to 7,561.67 on Friday and the Nasdaq dropped 0.9%, while the Dow edged up 0.1% to 52,347.55, AP reported. The S&P 500 still gained 2.5% for the week, its first weekly rise since October. Nvidia fell another 2% after CEO Jensen Huang's resignation, and the week's fallout has cut more than $600 billion from its market value; AMD fell 8.8% and Broadcom 4.8%. A report showed US wholesale inflation eased slightly but remains high, and the 10-year Treasury yield rose to 5.15%. Brent crude settled at $95.84 a barrel, and economists widely expect the Fed to raise rates in December.$n$,
  $n$Every rupee or dollar put into shares could instead earn a safe return in government bonds, so that safe return is the opportunity cost of owning stocks. When the 10-year Treasury pays over 5%, investors demand more from risky shares, and expensive tech stocks feel it first.$n$,
  $n$CP24 (AP); also KRMG (AP)$n$, $n$https://www.cp24.com/news/money/2026/11/13/us-futures-climb-as-wall-street-keeps-an-eye-on-nvidia-microsoft-and-producer-prices/$n$, $n$econ-06$n$, 'draft',
  $n$Nvidia has lost more than $600 billion in value in a week, more than most Indian companies are worth.$n$,
  $n$AI chip stocks fell again on Friday even as most US shares rose, and US bond yields climbed to 5.15%. When safe bonds pay that much, risky stocks have to work harder to attract money. The opportunity cost card explains the trade-off.$n$, false, $n$2026-11-14T03:08:00+05:30$n$, 6),
($n$2026-11-14-grasim-loss$n$, '2026-11-14', $n$recruiter$n$, $n$RESULTS$n$,
  $n$Grasim swings to ₹234 crore consolidated loss on a ₹767 crore pulp-venture write-down; standalone profit buoyed by UltraTech dividend$n$,
  $n$Aditya Birla group flagship Grasim Industries reported a consolidated net loss of ₹234 crore for the September quarter, against a profit of ₹595 crore a year earlier. The loss came from an exceptional charge of ₹767 crore for impairment and estimated exposure in its Canadian pulp joint venture, AV Group NB. Consolidated revenue rose 26% to ₹50,105 crore, and paints brand Birla Opus grew revenue 35% to ₹1,337 crore. On a standalone basis, Grasim earned ₹2,306 crore, helped by a ₹3,968 crore dividend from subsidiary UltraTech that is cancelled out when the group's accounts are combined. The shares traded about 2.8% lower after the results.$n$,
  $n$Under the business entity concept, each company keeps its own books, so Grasim alone counts UltraTech's dividend as income. In the consolidated accounts the whole group is treated as one entity, and money moving from one pocket to another is not income, so the dividend disappears.$n$,
  $n$Upstox News; also Grasim press release$n$, $n$https://upstox.com/news/market-news/earnings/grasim-industries-q2-fy-27-results-firm-reports-net-loss-of-234-crore-yo-y-revenue-grows-to-50-105-crore/article-203434/$n$, $n$acct-11$n$, 'draft',
  $n$Grasim made a ₹2,306 crore profit and a ₹234 crore loss in the same quarter. Both numbers are correct.$n$,
  $n$A big dividend from UltraTech lifted Grasim's own profit, but it vanishes when the group's accounts are combined, and a Canadian pulp write-down tipped the group into a loss. Which number you quote depends on the entity. The accounting concepts card explains why.$n$, false, $n$2026-11-13T15:03:00+05:30$n$, 7),
($n$2026-11-14-siam-pv-dispatches$n$, '2026-11-14', $n$india$n$, $n$AUTO$n$,
  $n$Car makers ship a record 5.19 lakh vehicles to dealers in October, up 12.4%, even as retail registrations fall 23.8%$n$,
  $n$Domestic passenger vehicle dispatches from factories to dealers rose 12.4% to a record 5.19 lakh units in October, industry body SIAM said on Friday, calling it the strongest October ever. Two-wheeler dispatches grew 16.1% to 25.78 lakh, led by a 31.6% jump in scooters, and total vehicle exports rose 26%. SIAM linked part of the growth to companies stocking dealers ahead of Dhanteras and Diwali, which fell in early November this year. By contrast, dealer body FADA's data showed retail sales to customers fell 23.8% in October, which it attributed to the festivals shifting to November from October last year.$n$,
  $n$Factory dispatches measure what companies ship to dealers, while retail registrations measure what customers actually buy. Good demand estimation looks at both, because a gap between them can mean dealers are stocking up for a coming rush or that unsold inventory is piling up.$n$,
  $n$Millennium Post (SIAM data)$n$, $n$https://www.millenniumpost.in/business/indias-domestic-pv-dispatches-grow-124-to-519-lakh-units-in-oct-siam-683135$n$, $n$mkt-10$n$, 'draft',
  $n$Factories sent a record number of cars to showrooms in October, but fewer buyers drove them home.$n$,
  $n$Dispatches to dealers hit an October record, while retail sales fell about 24% because Diwali shopping shifted to November. The two numbers tell different stories about demand. The market measurement card explains which one to trust and when.$n$, false, $n$2026-11-13T23:08:00+05:30$n$, 8),
($n$2026-11-14-bank-credit-19pc$n$, '2026-11-14', $n$india$n$, $n$BANKING$n$,
  $n$Bank loans grow 19.26% while deposits rise 16.76% as festive borrowing widens the gap, RBI data shows$n$,
  $n$Bank credit grew 19.26% from a year earlier in the fortnight ended October 31, up from 17.94% in the previous fortnight, according to RBI data released on Friday. Outstanding loans reached ₹237.03 lakh crore, with festive-season borrowing for consumer durables, homes and vehicles cited as drivers. Deposits grew more slowly, by 16.76%, to ₹288.16 lakh crore. That widened the gap between credit growth and deposit growth to 2.5 percentage points from 1.34 points. Banks' holdings of government securities rose 9.36% to ₹77.19 lakh crore.$n$,
  $n$Interest is the price of money. When demand for loans grows faster than the supply of deposits banks can lend, a shortage builds, and banks typically respond by offering higher deposit rates or charging more for loans until the market balances again.$n$,
  $n$Millennium Post (RBI data)$n$, $n$https://www.millenniumpost.in/business/bank-credit-growth-rises-to-1926-by-october-31-683127$n$, $n$econ-09$n$, 'draft',
  $n$Indians are borrowing faster than they are saving: loans grew 19% this Diwali season, deposits under 17%.$n$,
  $n$Festive buying of homes, cars and gadgets pushed bank lending growth to 19.26%, well ahead of deposit growth. Banks need to find the money somewhere. The market equilibrium card explains what happens when demand outruns supply.$n$, false, $n$2026-11-13T23:05:00+05:30$n$, 9),
($n$2026-11-14-sembcorp-green-ipo$n$, '2026-11-14', $n$india$n$, $n$IPO$n$,
  $n$SEBI clears Temasek-backed Sembcorp Green Infra's ₹3,750 crore IPO; all money raised to go to the company, mainly to cut debt$n$,
  $n$Sembcorp Green Infra, the Indian renewable energy arm of Singapore's Sembcorp Industries, has received SEBI's final observations for a ₹3,750 crore IPO, PTI reported on Friday. The issue will be entirely fresh shares, with no existing shareholder selling, so the money goes to the company. It plans to use most of it to repay or prepay borrowings of the company and some subsidiaries. As of March 31, 2026, it had a portfolio of about 7.64 GW across 105 projects in 13 states and union territories, with 3.60 GW operating and the rest under construction, and ranked among India's 10 largest renewable power producers by operating capacity.$n$,
  $n$The accounting equation says assets equal liabilities plus equity. Raising money by issuing shares and using it to repay loans lowers liabilities and raises equity, leaving the company less indebted without changing what it owns.$n$,
  $n$Millennium Post (PTI)$n$, $n$https://www.millenniumpost.in/business/temasek-backed-sembcorp-green-infra-gets-sebi-nod-for-3750-cr-initial-public-offering-683132$n$, $n$acct-09$n$, 'draft',
  $n$A Singapore-backed green power firm wants ₹3,750 crore from Indian investors, mostly to pay off loans.$n$,
  $n$SEBI has cleared Sembcorp Green Infra's IPO, made up entirely of new shares, so all the money goes into the company. Most of it will reduce debt. The accounting equation card shows what swapping loans for shareholder money does to a balance sheet.$n$, false, $n$2026-11-13T23:07:00+05:30$n$, 10),
($n$2026-11-14-adani-intellismart$n$, '2026-11-14', $n$india$n$, $n$DEALS$n$,
  $n$Adani Energy Solutions completes ₹3,050 crore acquisition of smart-meter firm IntelliSmart from NIIF and EESL$n$,
  $n$Adani Energy Solutions said in an exchange filing that it has completed the acquisition of 100% of IntelliSmart Infrastructure from the National Investment and Infrastructure Fund and state-run Energy Efficiency Services Limited for ₹3,050 crore, Millennium Post reported. The deal also covers redeeming debentures held by NIIF. IntelliSmart installs and runs advanced electricity meters and some smart gas meters. The Competition Commission of India approved the deal on October 30. When the agreement was signed in June, Adani said the purchase would make it India's largest smart-metering platform, with over 4.7 crore meters.$n$,
  $n$Buying a rival is one of the fastest ways to gain scale, which can lower costs per meter and strengthen bargaining power with suppliers. Porter's Five Forces helps explain why fewer, larger players change the competitive balance in an industry.$n$,
  $n$Millennium Post; also The Tribune (June deal details)$n$, $n$https://www.millenniumpost.in/business/adani-energy-solutions-acquires-smart-metering-player-intellismart-for-3050-crore-683147$n$, $n$mkt-06$n$, 'draft',
  $n$The smart meter on your building's wall may soon belong to Adani, after a ₹3,050 crore deal closed.$n$,
  $n$Adani Energy Solutions has completed its purchase of IntelliSmart, a large smart-meter operator. The company had said the deal makes it India's largest smart-metering platform. The Five Forces card explains why scale matters so much in an industry like this.$n$, false, $n$2026-11-14T00:22:00+05:30$n$, 11),
($n$2026-11-14-chandannagar-lights$n$, '2026-11-14', $n$local$n$, $n$KOLKATA$n$,
  $n$Chandannagar's light artists lose a reported ₹5 crore Strand contract to a Gujarat firm as they say orders have fallen by nearly half$n$,
  $n$A reported ₹5 crore contract to light up Chandannagar's Strand for Jagaddhatri Puja has gone to a Gujarat-based firm instead of the town's famous local illumination artists, Millennium Post reported. Somnath Seth, joint secretary of the local lighting artists' association, confirmed local artists did not get the contract. Artists and traders say their orders have fallen by nearly half; one artist said a Cooch Behar project worth ₹8 lakh last year is being done for ₹4 lakh this year. Rising prices of LEDs, wires and other materials are also squeezing their earnings, so many are taking smaller jobs to keep workers employed.$n$,
  $n$When buyers order less at every price, demand itself has shifted, which is different from people buying less because prices went up. Chandannagar's artists face that shift, while costlier LEDs and wires squeeze them from the supply side too.$n$,
  $n$Millennium Post$n$, $n$https://www.millenniumpost.in/bengal/gujarat-firm-bags-chandannagar-strand-lighting-contract-683183$n$, $n$econ-02$n$, 'draft',
  $n$Chandannagar's famous light artists didn't get to light up their own Strand this year. A Gujarat firm did.$n$,
  $n$A reported ₹5 crore contract went outside the town, and local artists say their orders have nearly halved while LED and wire prices rise. It is a story of demand moving away from a famous local craft. The change in demand card explains the difference between a demand shift and a price effect.$n$, true, $n$2026-11-14T00:45:00+05:30$n$, 12)
on conflict (slug) do update set
  publish_date = excluded.publish_date, lane = excluded.lane, tag = excluded.tag,
  headline = excluded.headline, summary = excluded.summary, concept_note = excluded.concept_note,
  source_name = excluded.source_name, source_url = excluded.source_url, card_id = excluded.card_id,
  published_at = excluded.published_at, rank = excluded.rank,
  -- the pick and teaser only fill in blanks, so changes made on the approval page are kept
  teaser_title = coalesce(news_stories.teaser_title, excluded.teaser_title),
  teaser = coalesce(news_stories.teaser, excluded.teaser),
  featured = news_stories.featured or (excluded.featured and not exists (
    select 1 from news_stories f where f.publish_date = excluded.publish_date and f.featured));

-- Check: this day's stories by lane
select lane, count(*) as stories, count(*) filter (where status = 'approved') as approved,
  count(*) filter (where featured) as todays_pick
from news_stories where publish_date = '2026-11-14' group by lane order by lane;

-- Check: the day's running order
select rank, lane, headline, status, featured from news_stories where publish_date = '2026-11-14' order by rank;
